#!/usr/bin/env bash
# tools/check-readme.sh — Verify README.md matches generated output

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
README="$ROOT/README.md"
TMP_README="$(mktemp)"

# Generate into temp file
"$ROOT/tools/build-readme.sh" > /dev/null 2>&1
# Actually, build-readme.sh writes to README.md directly, so we need a different approach

# Let's regenerate to a temp file
cat > "$TMP_README" <<'EOF'
<!-- generated by tools/build-readme.sh; do not edit -->

EOF

README_PARTS="$ROOT/docs/readme"
TRANSCRIPTS="$ROOT/demo/transcripts"

for part in "$README_PARTS"/*.md; do
  cat "$part" >> "$TMP_README"
  echo "" >> "$TMP_README"
done

awk -v transcripts="$TRANSCRIPTS" '
  /<!-- include:transcript:([^>]+) -->/ {
    match($0, /<!-- include:transcript:([^>]+) -->/, m)
    transcript = m[1]
    print "```console"
    while ((getline line < (transcripts "/" transcript)) > 0) {
      print line
    }
    close(transcripts "/" transcript)
    print "```"
    next
  }
  { print }
' "$TMP_README" > "$TMP_README.final" && mv "$TMP_README.final" "$TMP_README"

# Compare
if diff -u "$README" "$TMP_README" > /dev/null; then
  echo "README.md is up to date"
  rm -f "$TMP_README"
  exit 0
else
  echo "README.md has drifted from generated content:"
  diff -u "$README" "$TMP_README" || true
  rm -f "$TMP_README"
  exit 1
fi